    'Settings/SettingsWindow.Start.cs',
    'Settings/SettingsWindow.Stats.cs',
    'Settings/SettingsWindow.Targets.cs',
    'Settings/SettingsWindow.Widgets.cs'
)
$settingsRootPrefix = $pluginUiRoot.TrimEnd([char[]]@('\', '/')) +
    [System.IO.Path]::DirectorySeparatorChar
$settingsRelativePaths = @($settingsSourceFiles | ForEach-Object {
    $fullSettingsPath = [System.IO.Path]::GetFullPath($_.FullName)
    if (-not $fullSettingsPath.StartsWith(
            $settingsRootPrefix,
            [System.StringComparison]::OrdinalIgnoreCase)) {
        throw "SettingsWindow source escaped its expected root: $fullSettingsPath"
    }

    $fullSettingsPath.Substring($settingsRootPrefix.Length).Replace('\', '/')
})
$settingsLayoutDifference = @(
    Compare-Object -ReferenceObject $expectedSettingsRelativePaths -DifferenceObject $settingsRelativePaths
)
if ($settingsLayoutDifference.Count -ne 0) {
    $layoutDetails = $settingsLayoutDifference | ForEach-Object { "$($_.SideIndicator) $($_.InputObject)" }
    throw "SettingsWindow split layout drifted: $($layoutDetails -join ', ')"
}

$settingsWindow = ($settingsSourceFiles | ForEach-Object {
    Get-Content -LiteralPath $_.FullName -Raw -Encoding UTF8
}) -join "`n"
$normalizedSettingsWindow = $settingsWindow -replace '\s+', ' '
$settingsHud = Read-RequiredSource $settingsHudPath 'HUD and Nameplates settings page'
$settingsStats = Read-RequiredSource $settingsStatsPath 'Player Stats settings page'
$normalizedSettingsStats = $settingsStats -replace '\s+', ' '
$allowedUnsafe = @(
    $slotResolverPath,
    $readinessPath,
    $namePlateAnchorPath,
    $inputContextPath,
    $purifyProbePath,
    $astrologianHarmonicOrbisProbePath,
    $clientActionAttemptBoundaryPath,
    $allyRescueProbePath,
    $miracleInterceptProbePath,
    $defensiveUtilityProbePath,
    $pressureEscapeSprintProbePath,
    $smartSprintProbePath,
    $ninjaSeitonProbePath,
    $viperSerpentTailProbePath,
    $scholarCriticalStrategyProbePath,
    $smartKardiaProbePath,
    $smartRecuperateProbePath,
    $viperSerpentTailProbePath,
    $emergencyTeleportProbePath,
    $gunbreakerContinuationProbePath,
    $darkKnightShadowbringerProbePath,
    $darkKnightWolvesDenCurrentTargetResolverPath,
    $monkHeldComboProbePath,
    $samuraiReactiveCounterCcProbePath,
    $strictWolvesDenDummyResolverPath,
    $smartWardensPaeanServicePath,
    $heldCastCancellationServicePath,
    $bardRepellingShotProbePath,
    $isolationAwarenessPath,
    $autoEnemyFocusMarkPath,
    $reviewedPvpCommandDispatcherPath,
    $guardianCommunicationPath,
    $monkEarthReplyProbePath,
    $resourceAuraAnchorPath,
    $nearAssistPath,
    $partySlotResolverPath,
    $machinistLimitBreakCapturePath,
    $machinistLimitBreakWarningSoundPath,
    $targetPressureTrackerPath,
    $ccImmunityBrakeServicePath,
    $autoLowMpFocusTargetServicePath,
    $panicShukuchiServicePath,
    $ninjaGuardShukuchiProbePath,
    $redMageGuardEngageProbePath,
    $darkKnightPlungeProbePath,
    $combatLimitBreakCaptureBufferPath,
    $smartTabTargetingServicePath,
    $integratedActionBufferRuntimePath,
    $integratedActionBufferCompatibilityServicePath,
    $integratedHotbarInputSourcePath,
    $integratedInputRuntimePath,
    $crystallineConflictMapStatisticsServicePath,
    $crystallineConflictMapResultPacketPath,
    $crystallineConflictPredictionCaptureBufferPath,
    $crystallineConflictPredictionDirectorReaderPath,
    $crystallineConflictMedicineKitRendererPath,
    $opponentLimitBreakGaugeServicePath
)

$unsafeMatches = @(Select-String -LiteralPath $sourceFiles.FullName -Pattern '\bunsafe\b' |
    Where-Object { $_.Line -notmatch '^\s*"' })
$unexpectedUnsafe = @($unsafeMatches | Where-Object { $allowedUnsafe -notcontains $_.Path })
if ($unexpectedUnsafe.Count -gt 0) {
    $locations = $unexpectedUnsafe | ForEach-Object { "$($_.Path):$($_.LineNumber)" }
    throw "Unsafe code is allowed only in the reviewed native boundaries: $($locations -join ', ')"
}

# Near Assist, Smart Action, Near Help, Far Help, and the integrated immutable
# action-buffer dispatcher share one target-only UseAction detour. The integrated
# input boundary adds only reviewed standard-hotbar/input-state hooks.
# Smart Tab separately owns one paired native targeting-handler
# and world-cycle boundary. The
# MCH/pressure capture owns the read-only ActionEffect receive hook and forwards
# value-only activation/damage records to the bounded Combat LB buffer. The map
# statistics service owns one separately pinned post-match result hook. Explicit
# directional /seitonbw owns one same-lane local-facing preservation hook. The
# movement En Avant tracker uses only managed finite world-displacement samples.
# The medicine-kit renderer owns only its separately pinned read-only native
# content-timer and ready-to-draw reads.
# Plugin.cs only constructor-injects interop and the signature scanner.
$interopMatches = @(Select-String -LiteralPath $sourceFiles.FullName -Pattern '\b(IGameInteropProvider|Hook<|HookFromAddress)\b')
$unexpectedInterop = @($interopMatches | Where-Object {
    $_.Path -notin @(
        $pluginPath,
        $nearAssistPath,
        $panicShukuchiServicePath,
        $machinistLimitBreakCapturePath,
        $smartTabTargetingServicePath,
        $integratedHotbarInputSourcePath,
        $integratedInputRuntimePath,
        $crystallineConflictMapStatisticsServicePath)
})
if ($unexpectedInterop.Count -gt 0) {
    $locations = $unexpectedInterop | ForEach-Object { "$($_.Path):$($_.LineNumber)" }
    throw "Only Near Assist/Smart Action, explicit directional /seitonbw, Smart Tab, integrated standard-hotbar input, and the reviewed read-only combat/post-match captures may own native hooks: $($locations -join ', ')"
}
$pluginSource = Read-RequiredSource $pluginPath 'Plugin entry point'
if ([regex]::Matches($pluginSource, '\bIGameInteropProvider\b').Count -ne 1 -or
    [regex]::Matches($pluginSource, '\bISigScanner\b').Count -ne 1 -or
    $pluginSource -match '\b(ScanText|SignatureAttribute|MinHook)\b' -or
    $pluginSource -match '\b(Hook<|HookFromAddress)\b') {
    throw 'Plugin.cs may only constructor-inject one IGameInteropProvider and one ISigScanner; it may not scan or create a hook.'
}

# The integrated buffer/Turbo boundary reuses NearAssist's sole UseAction hook.
# Native standard-hotbar input is certified by a closed four-hook allowlist:
# ExecuteSlot, ExecuteSlotById, IsInputIdPressed, and CheckHotbarBindings.
$integratedInputRuntime = Read-RequiredSource $integratedInputRuntimePath 'Integrated input coordinator'
$normalizedIntegratedInputRuntime = $integratedInputRuntime -replace '\s+', ' '
$integratedHotbarInputSource = Read-RequiredSource $integratedHotbarInputSourcePath 'Integrated native hotbar input source'
$normalizedIntegratedHotbarInputSource = $integratedHotbarInputSource -replace '\s+', ' '
$integratedActionBufferRuntime = Read-RequiredSource $integratedActionBufferRuntimePath 'Integrated action-buffer runtime'
$normalizedIntegratedActionBufferRuntime = $integratedActionBufferRuntime -replace '\s+', ' '
$integratedActionBufferCompatibilityService = Read-RequiredSource $integratedActionBufferCompatibilityServicePath 'Integrated action-buffer compatibility service'
$normalizedIntegratedActionBufferCompatibilityService = $integratedActionBufferCompatibilityService -replace '\s+', ' '
$smartActionBufferCompatibilityRules = Read-RequiredSource $smartActionBufferCompatibilityRulesPath 'Smart action-buffer compatibility rules'
$normalizedSmartActionBufferCompatibilityRules = $smartActionBufferCompatibilityRules -replace '\s+', ' '
$smartActionBufferCompatibilitySelfTests = Read-RequiredSource $smartActionBufferCompatibilitySelfTestsPath 'Smart action-buffer compatibility self-tests'
$physicalHoldLatch = Read-RequiredSource $physicalHoldLatchPath 'Physical hold-latch core'
$normalizedPhysicalHoldLatch = $physicalHoldLatch -replace '\s+', ' '
$physicalHoldLatchSelfTests = Read-RequiredSource $physicalHoldLatchSelfTestsPath 'Physical hold-latch self-tests'
$logicalHotbarRepeatPolicy = Read-RequiredSource $logicalHotbarRepeatPolicyPath 'Logical hotbar repeat policy'
$normalizedPluginForIntegratedInput = $pluginSource -replace '\s+', ' '
$normalizedNearAssistForIntegratedInput = (Read-RequiredSource $nearAssistPath 'Sole UseAction owner for integrated input') -replace '\s+', ' '

# Synthetic replay is fail-closed around the two explicitly audited action
# mutators. The pure rule owns the one-frame quarantine, while the service may
# refresh its cached profile only on topology change or the bounded five-second
# cadence. Foreign configuration/IPC is read live at Arm and Dispatch only;
# native input and native Turbo never depend on this service.
Assert-Literals $smartActionBufferCompatibilityRules @(
    'public const int CleanFrameworkFramesAfterChange = 1;',
    'input.AssessmentAvailable &&',
    '!input.Quarantined &&',
    'SmartActionBufferReActionProfile.NotLoaded or',
    'SmartActionBufferReActionProfile.AuditedSafe &&',
    '(!input.MOActionLoaded || input.MOActionOwnershipPublished);',
    'public static bool AllowsExactReviewedSelfAction(',
    'SmartActionBufferReActionProfile.AuditedMutationActive &&',
    '!reActionOwnsExactAction &&',
    'public static bool SignatureChanged(',
    'public static int MarkChanged(int remainingCleanFrames) =>',
    'public static int ConsumeCleanFrameworkFrame(int remainingCleanFrames) =>'
) 'Pure generic-buffer and exact reviewed-self-action compatibility policies'
if ($normalizedSmartActionBufferCompatibilityRules -notmatch 'public static bool AllowsMutation\(SmartActionBufferCompatibilityInput input\) => input\.AssessmentAvailable && !input\.Quarantined && input\.ReActionProfile is SmartActionBufferReActionProfile\.NotLoaded or SmartActionBufferReActionProfile\.AuditedSafe && \(!input\.MOActionLoaded \|\| input\.MOActionOwnershipPublished\);' -or
    $normalizedSmartActionBufferCompatibilityRules -notmatch 'public static bool AllowsExactReviewedSelfAction\( SmartActionBufferCompatibilityInput input, bool reActionOwnsExactAction\) => input\.AssessmentAvailable && !input\.Quarantined && input\.ReActionProfile is SmartActionBufferReActionProfile\.NotLoaded or SmartActionBufferReActionProfile\.AuditedSafe or SmartActionBufferReActionProfile\.AuditedMutationActive && !reActionOwnsExactAction && \(!input\.MOActionLoaded \|\| input\.MOActionOwnershipPublished\);') {
    throw 'Generic synthetic replay must still require a fully non-mutating profile, while the exact reviewed self-action exception may admit audited unrelated ReAction mutation only after exact ownership is disproven; unavailable, quarantined, unknown, exact-owned, or unreadable-MOAction states remain blocked.'
}
Assert-Literals $integratedActionBufferCompatibilityService @(
    'private const string MOActionRetargetedActionsIpc = "MOAction.RetargetedActions";',
    'private const int RefreshIntervalMilliseconds = 5_000;',
    'private const int MaximumReActionStackSelectors = 8_192;',
    'private static readonly Version SupportedReActionVersion = new(1, 3, 5, 1);',
    'private static readonly Version SupportedMOActionVersion = new(4, 10, 1, 0);',
    'pluginInterface.ActivePluginsChanged += OnActivePluginsChanged;',
    'pluginInterface.ActivePluginsChanged -= OnActivePluginsChanged;',
    'refresh = dirty || now >= nextRefreshAt;',
    'nextRefreshAt = SaturatingAdd(now, RefreshIntervalMilliseconds);',
    'internal bool CanMutateAction(',
    'internal bool CanDispatchExactReviewedSelfAction(',
    'private static bool TryCaptureLiveReActionExactProfile(',
    'private static bool TryReadReActionActionStackSelectors(',
    'private static unsafe bool TryDetermineReActionExactSelfActionOwnership(',
    '"ReAction.Configuration+ActionStack"',
    '"ReAction.Configuration+Action"',
    '"UseAdjustedID"',
    'selector.ActionId == 0',
    'selector.ActionId is 1 or 2',
    'actionManager->GetAdjustedActionId(',
    'private readonly record struct ReActionActionSelector(',
    'string ActionSelectorSignature,',
    'ReActionActionSelector[] ActionSelectors);',
    'internal bool IsCachedMutationAllowed(out string reason)',
    'private void OnActivePluginsChanged(IActivePluginsChangedEventArgs _)',
    'Interlocked.Exchange(ref topologyDirty, 1);',
    'remainingCleanFrames =',
    'SmartActionBufferCompatibilityRules.MarkChanged(',
    'SmartActionBufferCompatibilityRules.ConsumeCleanFrameworkFrame('
) 'Bounded in-memory ReAction/MOAction compatibility boundary'
$cachedCompatibilityGateMatch = [regex]::Match(
    $integratedActionBufferCompatibilityService,
    '(?s)internal bool IsCachedMutationAllowed\(out string reason\).*?\r?\n    \}\r?\n\r?\n    public void Dispose')
if (-not $cachedCompatibilityGateMatch.Success -or
    $cachedCompatibilityGateMatch.Value -match '\b(?:InstalledPlugins|GetIpcSubscriber|GetAssemblies|GetPlugin|Assess|RefreshAssessment)\b' -or
    [regex]::Matches($integratedActionBufferCompatibilityService, '\bActivePluginsChanged\b').Count -ne 2 -or
    [regex]::Matches($integratedActionBufferCompatibilityService, '\bInstalledPlugins\b').Count -ne 1 -or
    [regex]::Matches($integratedActionBufferCompatibilityService, '\bGetIpcSubscriber<uint\[\]>\s*\(').Count -ne 2 -or
    $integratedActionBufferCompatibilityService -match '\b(?:System\.IO|File\.|Directory\.|Hook<|HookFromAddress|UseAction|LogicalHotbarRepeatEngine|IntegratedHotbarInputSource|EnableNativeHotbarTurbo)\b' -or
    [regex]::Matches($integratedActionBufferCompatibilityService, '\bunsafe\b').Count -ne 1 -or
    [regex]::Matches($integratedActionBufferCompatibilityService, '\bActionManager\.Instance\s*\(').Count -ne 1 -or
    [regex]::Matches($integratedActionBufferCompatibilityService, '\bactionManager->GetAdjustedActionId\s*\(').Count -ne 1 -or
    [regex]::Matches($integratedActionBufferCompatibilityService, '(?m)^\s*internal bool CanDispatchExactReviewedSelfAction\s*\(').Count -ne 1 -or
    [regex]::Matches($integratedActionBufferCompatibilityService, '(?m)^\s*private static unsafe bool TryDetermineReActionExactSelfActionOwnership\s*\(').Count -ne 1 -or
    $normalizedIntegratedActionBufferCompatibilityService -notmatch 'private static bool TryReadReActionActionStackSelectors\(.*?stackCollection\.Count > MaximumReActionStackSelectors.*?\+\+actionStackCount > MaximumReActionStackSelectors.*?"ReAction\.Configuration\+ActionStack".*?captured\.Count >= MaximumReActionStackSelectors.*?"ReAction\.Configuration\+Action".*?"ID".*?"UseAdjustedID".*?captured\.Add\(new ReActionActionSelector\( actionStackCount - 1, actionId, useAdjustedActionId\)\);.*?exactCollection\.Count != actionStackCount.*?selectors = captured\.ToArray\(\); selectorSignature = CreateReActionActionSelectorSignature\( actionStackCount, selectors\); return true;' -or
    $normalizedIntegratedActionBufferCompatibilityService -notmatch 'private static unsafe bool TryDetermineReActionExactSelfActionOwnership\(.*?if \(configuration is null\) return true;.*?foreach \(var selector in configuration\.ActionSelectors\).*?if \(selector\.ActionId == 0\).*?ownsExactAction = true; return true;.*?if \(selector\.ActionId is 1 or 2\) continue;.*?if \(selector\.UseAdjustedActionId\).*?ActionManager\.Instance\(\).*?actionManager->GetAdjustedActionId\( selector\.ActionId\).*?if \(selectedActionId != requestedActionId && selectedActionId != resolvedActionId\).*?continue;.*?ownsExactAction = true; return true;.*?catch.*?reason = "ReAction exact action ownership became unreadable"; return false;' -or
    $normalizedIntegratedActionBufferCompatibilityService -notmatch 'private static bool TryReadReActionConfigurationObject\(.*?try.*?TryReadReActionActionStackSelectors\(.*?configuration = new ReActionConfigurationSnapshot\( actionStackCount, autoTargetEnabled, selectorSignature, actionSelectors\); return true;.*?catch.*?configuration = null!; return false;' -or
    $normalizedIntegratedActionBufferCompatibilityService -notmatch 'internal bool CanDispatchExactReviewedSelfAction\(.*?expected = assessment; expectedReAction = auditedReActionConfiguration; weakReAction = liveReActionConfiguration; generation = assessmentGeneration;.*?AllowsExactReviewedSelfAction\( profileInput, reActionOwnsExactAction: false\).*?TryReadMOActionOwnership\( requestedActionId, resolvedActionId, expected\.MOActionOwnershipSignature, out actionIsUnowned, out var ownershipReason\).*?expected\.MOActionLoaded && !actionIsUnowned.*?TryCaptureLiveReActionExactProfile\( expectedReAction, weakReAction, out var currentReAction\).*?TryDetermineReActionExactSelfActionOwnership\( currentReAction, requestedActionId, resolvedActionId, out var reActionOwnsExactAction, out var reActionReason\).*?AllowsExactReviewedSelfAction\( exactInput, reActionOwnsExactAction\).*?generation == assessmentGeneration && Volatile\.Read\(ref topologyDirty\) == 0 && !quarantinedThisFrame && SmartActionBufferCompatibilityRules\.AllowsExactReviewedSelfAction\( stableInput, reActionOwnsExactAction\).*?return true;' -or
    $integratedActionBufferCompatibilityService -match '\.SetValue\s*\(' -or
    $integratedInputRuntime -match '\b(?:IntegratedActionBufferCompatibilityService|SmartActionBufferCompatibilityRules)\b' -or
    $integratedHotbarInputSource -match '\b(?:IntegratedActionBufferCompatibilityService|SmartActionBufferCompatibilityRules)\b') {
    throw 'Compatibility must remain read-only: generic buffering uses the cached/live non-mutation checks, while the exact reviewed self-action boundary alone may re-read bounded ReAction selectors plus MOAction ownership and resolve adjusted IDs without action use, target/input mutation, file scan, hook, Turbo gate, retry, or per-frame foreign reflection/IPC.'
}
if ($normalizedIntegratedActionBufferRuntime -notmatch 'compatibility = new IntegratedActionBufferCompatibilityService\(pluginInterface\);.*?compatibility\.Start\(\); framework\.Update \+= OnFrameworkUpdate;' -or
    $normalizedIntegratedActionBufferRuntime -notmatch 'internal bool CanDispatchExactReviewedSelfAction\( uint requestedActionId, uint resolvedActionId, out string reason\) => compatibility\.CanDispatchExactReviewedSelfAction\( requestedActionId, resolvedActionId, out reason\);' -or
    [regex]::Matches($integratedActionBufferRuntime, '(?m)^\s*internal bool CanDispatchExactReviewedSelfAction\s*\(').Count -ne 1 -or
    $integratedActionBufferRuntime -match '\bCanDispatchExactExternalAction\b' -or
    $normalizedIntegratedActionBufferRuntime -notmatch 'private void OnFrameworkUpdate\(IFramework _\).*?compatibility\.OnFrameworkBoundary\(\);.*?if \(!compatibility\.IsCachedMutationAllowed\(out var cachedCompatibilityReason\)\).*?CancelPendingLocked\( SmartActionBufferCancelReason\.Conflict,.*?countCancellation: true\);.*?return;' -or
    $normalizedIntegratedActionBufferRuntime -notmatch 'CompleteExactStandardHotbarRoot\(.*?compatibility\.CanMutateAction\( candidate\.Request\.RequestedActionId, candidate\.Request\.ResolvedActionId, IntegratedActionBufferCompatibilityCheck\.Arm, out var compatibilityReason\).*?nativeAfterCompatibility = CaptureNativeState\(.*?snapshotAfterCompatibility = CaptureSnapshot\(.*?IsStableArmBoundaryAfterCompatibility\( candidate, nativeAfterCompatibility, snapshotAfterCompatibility\).*?engine\.Arm\( exactTemporalIntent, candidate\.CapturedAtMilliseconds, window\)' -or
    $normalizedIntegratedActionBufferRuntime -notmatch 'compatibility\.CanMutateAction\( candidate\.Request\.RequestedActionId, candidate\.Request\.ResolvedActionId, IntegratedActionBufferCompatibilityCheck\.Dispatch, out var compatibilityReason\).*?finalActionManager = ActionManager\.Instance\(\);.*?finalSnapshot = CaptureSnapshot\(.*?finalNative = CaptureNativeState\(.*?pendingRuntime = null; dispatching = true; dispatch = dispatcher; request = candidate\.Request;.*?dispatchResult = dispatch\(request\);' -or
    $normalizedIntegratedActionBufferRuntime -notmatch 'compatibility\.Dispose\(\);') {
    throw 'The buffer must use a cached frame gate, live Arm validation, and one live Dispatch validation followed by full tuple/context revalidation immediately before its sole replay.'
}

$useActionHookMatches = @(Select-String -LiteralPath $sourceFiles.FullName -Pattern 'HookFromAddress<ActionManager\.Delegates\.UseAction>')
if ($useActionHookMatches.Count -ne 1 -or
    $useActionHookMatches[0].Path -ne $nearAssistPath -or
    $integratedInputRuntime -match 'Hook(?:FromAddress)?<ActionManager\.Delegates\.UseAction>' -or
    $integratedActionBufferRuntime -match 'Hook(?:FromAddress)?<ActionManager\.Delegates\.UseAction>' -or
    $integratedHotbarInputSource -match 'Hook(?:FromAddress)?<ActionManager\.Delegates\.UseAction>') {
    $locations = $useActionHookMatches | ForEach-Object { "$($_.Path):$($_.LineNumber)" }
    throw "NearAssistRedirector must remain the only UseAction hook owner; integrated input may only call through it: $($locations -join ', ')"
}
Assert-Literals $integratedInputRuntime @(
    'HookFromAddress<RaptureHotbarModule.Delegates.ExecuteSlot>',
    'HookFromAddress<RaptureHotbarModule.Delegates.ExecuteSlotById>',
    'new IntegratedHotbarInputSource(',
    'GetHotbarInputSettings,',
    'OnCertifiedPhysicalPress,',
    'OnUnconsumedInjectedRepeat,',
    'nearAssist.IsSamuraiCastMovementSuppressed())',
    'var replayIntent = CreateBufferedReplayIntent(request);',
    'request.ResolvedActionId,',
    'request.RequiresSmartActionProtectionRecheck,',
    'var replay = nearAssist.RunExactBufferedReplay(',
    'replayIntent,',
    '() => actionManager->UseAction(',
    'request.ActionType,',
    'request.RequestedActionId,',
    'request.TargetId,',
    'request.ExtraParam,',
    'request.Mode,',
    'request.ComboRouteId));',
    'if (!replay.NativeBoundaryInvoked)',
    'return IntegratedActionBufferDispatchResult.NotInvoked;',
    'ClientActionAttemptBoundaryRules.Classify(',
    'NativeBoundaryInvoked: true,'
) 'Integrated input closed hook, sole-UseAction dispatch, and explicit native-boundary outcome classification'
if ($normalizedIntegratedInputRuntime -match
    '!condition\[ConditionFlag\.BeingMoved\] && nearAssist\.IsSamuraiCastMovementSuppressed\(\)') {
    throw '/seitonsam movement suppression must not disable itself when ordinary movement sets BeingMoved.'
}
Assert-Literals $integratedHotbarInputSource @(
    'HookFromAddress<InputData.Delegates.IsInputIdPressed>',
    'HookFromAddress<InputData.Delegates.IsInputIdDown>',
    'HookFromAddress<InputData.Delegates.IsInputIdHeld>',
    'HookFromSignature<CheckHotbarBindingsDelegate>',
    'pressedHook.Enable();',
    'downHook.Enable();',
    'heldHook.Enable();',
    'TryDisable(heldHook);',
    'TryDisable(downHook);',
    'downHook.Original((InputData*)inputAddress, (InputId)inputCode)',
    'heldHook.Original((InputData*)inputAddress, (InputId)inputCode)',
    'samuraiMovementBoundary.Read(',
    'HookFromAddress<InputManager.Delegates.GetInputStatus>',
    'HookFromAddress<InputManager.Delegates.IsAutoRunning>',
    'controlInputHook!.Original((InputManager*)inputAddress, (InputCode)inputCode)',
    'autorunHook!.Original()',
    'try { autorunHook?.Dispose(); } catch { }',
    'try { controlInputHook?.Dispose(); } catch { }',
    'checkHotbarBindingsHook.Original(context, mode);',
    'unconsumedInjectedRepeat = TakeUnconsumedInjectedRepeat(scanId);',
    'ClearPendingForScan(scanId);',
    'onUnconsumedInjectedRepeat(activation);',
    'reportPressed = decision.ShouldReportPressed;',
    'pending.Activation.Kind != IntegratedHotbarActivationKind.InjectedRepeat',
    'return pending.Activation;'
) 'Native logical-hotbar scan ownership, true injected-repeat result, and diagnostic miss handoff'

# Reconfiguration and lifecycle cancellation discard every prior physical
# identity. A key already down after that boundary is observed only as
# NeedsRelease; its exact raw key-up can clear the gate but can never certify a
# replacement press.
Assert-Literals $physicalHoldLatch @(
    'public PhysicalHoldDecision ObserveRequiredRelease(',
    'if (state != PhysicalHoldLatchState.NeedsRelease || !chord.IsValid)',
    'return ObserveNeedsRelease(new PhysicalHoldObservation(',
    'RawPressed: false,',
    'RawDown: rawDown));'
) 'Physical hold lifecycle-release boundary'
Assert-Literals $integratedHotbarInputSource @(
    'private PhysicalHoldLatch[] holdLatches = CreateHoldLatches();',
    'var gatedInputs = repeatEngine.CancelAndRequireRelease();',
    'repeatEngine.ReconfigureAndRequireRelease(options);',
    'holdLatches = CreateHoldLatches();',
    'if (latchSnapshot.State == PhysicalHoldLatchState.NeedsRelease &&',
    'latchSnapshot.Chord.IsValid)',
    'var rawDown = IsPhysicalKeyDown(',
    'return latch.ObserveRequiredRelease(nativePressed, rawDown);'
) 'Native adapter latch rebuild and exact release observation'
if ([regex]::Matches($integratedHotbarInputSource, 'holdLatches\s*=\s*CreateHoldLatches\(\);').Count -ne 3 -or
    [regex]::Matches($integratedHotbarInputSource, '\bObserveRequiredRelease\s*\(').Count -ne 1 -or
    $normalizedIntegratedHotbarInputSource -notmatch 'public int CancelAndRequireRelease\(\).*?repeatEngine\.CancelAndRequireRelease\(\); Array\.Clear\(pendingActivations\); Array\.Clear\(currentPresses\); holdLatches = CreateHoldLatches\(\); currentInputDataAddress = nint\.Zero; AdvanceLifecycle\(\);' -or
    $normalizedIntegratedHotbarInputSource -notmatch 'private void EnsureEngine\(IntegratedHotbarInputSettings settings\).*?repeatEngine\.ReconfigureAndRequireRelease\(options\); Array\.Clear\(currentPresses\); Array\.Clear\(pendingActivations\); holdLatches = CreateHoldLatches\(\); AdvanceLifecycle\(\);' -or
    $normalizedIntegratedHotbarInputSource -notmatch 'latchSnapshot\.State == PhysicalHoldLatchState\.NeedsRelease.*?IsPhysicalKeyDown\( inputData, latchSnapshot\.Chord\.PhysicalKey\); return latch\.ObserveRequiredRelease\(nativePressed, rawDown\);' -or
    [regex]::Matches($physicalHoldLatchSelfTests, '\blatch\.ObserveRequiredRelease\s*\(').Count -ne 2) {
    throw 'Lifecycle/configuration resets must rebuild the physical latches and require the already-held exact key to reach raw key-up before any new press can be certified.'
}

if ([regex]::Matches($integratedInputRuntime, 'HookFromAddress<RaptureHotbarModule\.Delegates\.ExecuteSlot>').Count -ne 1 -or
    [regex]::Matches($integratedInputRuntime, 'HookFromAddress<RaptureHotbarModule\.Delegates\.ExecuteSlotById>').Count -ne 1 -or
    [regex]::Matches($integratedHotbarInputSource, 'HookFromAddress<InputData\.Delegates\.IsInputIdPressed>').Count -ne 1 -or
    [regex]::Matches($integratedHotbarInputSource, 'HookFromAddress<InputData\.Delegates\.IsInputIdDown>').Count -ne 1 -or
    [regex]::Matches($integratedHotbarInputSource, 'HookFromAddress<InputData\.Delegates\.IsInputIdHeld>').Count -ne 1 -or
    [regex]::Matches($integratedHotbarInputSource, '\bpressedHook\.Enable\s*\(').Count -ne 1 -or
    [regex]::Matches($integratedHotbarInputSource, '\bdownHook\.Enable\s*\(').Count -ne 1 -or
    [regex]::Matches($integratedHotbarInputSource, '\bheldHook\.Enable\s*\(').Count -ne 1 -or
    [regex]::Matches($integratedHotbarInputSource, '\bTryDisable\(heldHook\)').Count -ne 1 -or
    [regex]::Matches($integratedHotbarInputSource, '\bTryDisable\(downHook\)').Count -ne 1 -or
    $integratedHotbarInputSource -match 'HookFromAddress<InputData\.Delegates\.IsInputIdReleased>' -or
    [regex]::Matches($integratedHotbarInputSource, 'HookFromSignature<CheckHotbarBindingsDelegate>').Count -ne 1 -or
    [regex]::Matches($integratedInputRuntime, '\bactionManager->UseAction\s*\(').Count -ne 1 -or
