) 'Shared-policy Smart Recuperate runtime'
Assert-Literals $smartRecuperateProbe @(
    '(intent.IsAutomatic &&',
    '!automaticRecoveryBasicShotCancellationEnabled ||',
    '!automaticRecoveryBasicShotMetadataVerified',
    'HasExactAutomaticRecoveryBasicShotCastBoundary(localPlayer)',
    'AutomaticRecoveryShotCastRules',
    '.IsExactAllowedPairWithAdjustedIdentity(',
    'intent.IsAutomatic ? 0 : intent.FrozenKeyCode,',
    'intent.IsAutomatic ||',
    'HeldCastCancellationHelperKind.SmartRecuperate,',
    'intent.HealthEventToken);'
) 'Automatic Recuperate exact keyless BRD/MCH cast-cancel request boundary'
Assert-Literals $smartRecuperateProbe @(
    'var stealthSuppressed = NinjaShukuchiStealthGate.IsActive(',
    'NinjaShukuchiStealthGate.ShouldSuppressAutomaticRecovery(',
    'var effectiveHeldModeEnabled = heldModeEnabled;',
    'var effectiveAutomaticModeEnabled = automaticModeEnabled;',
    'var frozenModeSuppressed = state.Intent switch',
    '{ IsAutomatic: true } => automaticStealthSuppressed,',
    '{ IsAutomatic: false } => stealthSuppressed,',
    '_ when automaticModeEnabled => automaticStealthSuppressed,',
    '_ => heldModeEnabled && stealthSuppressed,',
    'var recoverySuppressedByGuardOrStealth =',
    'actionHelpersSuppressedByGuard || frozenModeSuppressed;',
    'var effectiveHardReset = hardReset || nowMilliseconds < 0;',
    'intent.IsAutomatic',
    '? NinjaShukuchiStealthGate.ShouldSuppressAutomaticRecovery(',
    'NinjaShukuchiStealthGate.IsActive('
) 'Ninja Hidden blocks both Recuperate modes without erasing duplicate-safety latches, while automatic mode additionally fails closed on unverifiable NIN metadata'
if ([regex]::Matches($smartRecuperateProbe, '\bNinjaShukuchiStealthGate\.IsActive\s*\(').Count -ne 3 -or
    [regex]::Matches($smartRecuperateProbe, '\bNinjaShukuchiStealthGate\.ShouldSuppressAutomaticRecovery\s*\(').Count -ne 3) {
    throw 'Recuperate must check exact Hidden at observation, cast-cancel construction, and final dispatch for both held and automatic consent.'
}
if ($normalizedSmartRecuperateProbe -notmatch 'var inputClaimed = decision\.ShouldConsumeInputGeneration; if \(state\.Intent is \{ IsValid: true, IsAutomatic: false \} claimedIntent\).*?inputFrame\.IsFrozenGameplayKeyConsentValid\( \(VirtualKey\)claimedIntent\.FrozenKeyCode\);.*?if \(inputClaimed\) inputFrame\.Consume\(\);.*?if \(decision\.ShouldDispatch && decision\.Intent is \{ \} intent\).*?TryUseRecuperate' -or
    $normalizedSmartRecuperateProbe -notmatch 'private HeldCastCancellationRequest\? BuildCastCancellationRequest\(.*?currentState\.Intent is not \{ IsValid: true \} intent \|\| \(intent\.IsAutomatic && \(!automaticRecoveryBasicShotCancellationEnabled \|\| !automaticRecoveryBasicShotMetadataVerified\)\).*?\(intent\.IsAutomatic && !HasExactAutomaticRecoveryBasicShotCastBoundary\(localPlayer\)\).*?SmartRecuperateRules\.CanUseFrozenIntent\(.*?intent\.IsAutomatic \? 0 : intent\.FrozenKeyCode, intent\.IsAutomatic \|\| inputFrame\.IsFrozenGameplayKeyConsentValid\( \(VirtualKey\)intent\.FrozenKeyCode\).*?return new HeldCastCancellationRequest\(' -or
    $normalizedSmartRecuperateProbe -notmatch 'if \(effectiveAutomaticModeEnabled\).*?inputProbeSucceeded = TryGetTextInputState\(out textInputActive\);.*?if \(!inputProbeSucceeded\) textInputActive = true;' -or
    $normalizedSmartRecuperateProbe -notmatch 'var textInputActive = intent\.IsAutomatic \? !TryGetTextInputState\(out var currentTextInputActive\) \|\| currentTextInputActive : inputFrame\.Snapshot\.IsTextInputActive;' -or
    $normalizedSmartRecuperateRules -notmatch 'Context is SupportedPvPContext\.CrystallineConflict or SupportedPvPContext\.WolvesDen' -or
    $normalizedSmartRecuperateRules -notmatch 'intent\.IsValid && configurationEnabled && \(intent\.IsAutomatic \? automaticModeEnabled : heldModeEnabled\) && currentContext == intent\.Context' -or
    $normalizedSmartRecuperateRules -notmatch 'observation\.AutomaticModeEnabled \? 0 : observation\.HeldGameplayKeyCode.*?observation\.AutomaticModeEnabled \? SmartRecuperateTriggerKind\.Automatic : SmartRecuperateTriggerKind\.HeldGameplayKey' -or
    $normalizedSmartRecuperateProbe -notmatch 'PvPMatchRules\.ResolveSupportedContext\( clientState\.IsPvP, clientState\.IsPvPExcludingDen, includeWolvesDenTesting: configuration\.EnableWolvesDenTesting,' -or
    [regex]::Matches($smartRecuperateProbe, '\bUseAction\s*\(').Count -ne 1 -or
    [regex]::Matches($smartRecuperateProbe, '\bClientActionAttemptBoundary\.Capture\s*\(').Count -lt 2 -or
    [regex]::Matches($smartRecuperateProbe, '\bClientActionAttemptBoundaryRules\.ClassifyCriticalRecovery\s*\(').Count -ne 1 -or
    [regex]::Matches($smartRecuperateProbe, '\binputFrame\.Consume\s*\(').Count -ne 1 -or
    $smartRecuperateProbe -match '\bTryGetRecentExactLocalGuardAttempt\s*\(' -or
    $smartRecuperateProbe -match '\b(?:ITargetManager|TargetManager|SetTarget|Hook<|HookFromAddress|QueueAction|PendingDispatch)\b|\.(Target|FocusTarget|SoftTarget|MouseOverTarget|GPoseTarget)\s*=') {
    throw 'Smart Recuperate must freeze distinct held/automatic identities, give automatic consent key zero, yield only to exact live Guard (never the provisional request latch), limit its optional cast-cancel to the exact verified BRD/MCH shot, fail closed on text input, claim only its current scheduler frame, and issue one exact frozen self-GOID boundary with no retarget, alternate, or replay.'
}
$tryUseRecuperate = [regex]::Match(
    $normalizedSmartRecuperateProbe,
    'private ClientActionAttemptOutcome TryUseRecuperate\((?<Body>.*?)(?=private HeldCastCancellationRequest\? BuildCastCancellationRequest\()')
if (-not $tryUseRecuperate.Success -or
    $tryUseRecuperate.Groups['Body'].Value -match 'return ClientActionAttemptOutcome\.NotInvoked;' -or
    [regex]::Matches(
        $tryUseRecuperate.Groups['Body'].Value,
        'return ClientActionAttemptOutcome\.SoftUnavailable;').Count -ne 4) {
    throw 'Smart Recuperate pre-native validation must retain the exact health episode as one of four budget-free SoftUnavailable waits; only a crossed native boundary may spend or terminate it.'
}
$physicalObserverIntegration = [regex]::Match(
    $normalizedAutomaticRecoveryPersonalStatus,
    'var anyPersistentHeldInputEnabled = (?<Body>.*?)var purify = emergencyPurify\.Observe\(')
if (-not $physicalObserverIntegration.Success -or
    $physicalObserverIntegration.Groups['Body'].Value -match 'smartRecuperateAutomaticConfigurationEnabled|automaticPurifyConfigurationEnabled|EnableAutomatic(?:Purify|Recuperate)' -or
    $normalizedAutomaticRecoveryPersonalStatus -notmatch 'var purifyPhysicalInputObservationEnabled = heldPurifyConfigurationEnabled;' -or
    $normalizedAutomaticRecoveryPersonalStatus -notmatch 'var smartRecuperateHeldInputEnabled = configuration\.Enabled && configuration\.EnableSmartRecuperateOnHeldKey.*?var smartRecuperateAutomaticConfigurationEnabled = configuration\.Enabled && configuration\.EnableAutomaticRecuperate' -or
    $normalizedAutomaticRecoveryPersonalStatus -notmatch 'emergencyInput\.Observe\(.*?purifyPhysicalInputObservationEnabled.*?smartRecuperateHeldInputEnabled.*?purifyHeldInputEnabled,.*?smartRecuperateHeldInputEnabled,') {
    throw 'Automatic Purify/Recuperate and the keyless high-pressure Stun chain must not start, prime, or retire the shared physical held-key observer; only their separate physical/held modes may participate in that lifecycle.'
}

# VPR Serpent's Tail is a separate default-off physical-hold helper. It polls
# carrier 39183 directly on every eligible VPR framework frame and may freeze
# only the exact currently exposed 39174-39182 follow-up, current hard target,
# context, and held key. One carrier flicker cannot rearm a spent exposure; two
# consecutive non-follow-up observations establish a reset. CC accepts only a
# canonical S1-S5 current hard target; explicit Wolves' Den testing replaces the
# e-slot with the exact current native hard target. Its duel branch mirrors the
# working GNB direct object-table path, independently proves a live hostile
# player, and does not depend on PvPDuelManager.EnemyEntityId. The separately
# reviewed exact verified striking dummy remains supported. Duel targeting
# depends only on the action sheet, never dummy metadata.
# The helper owns one
# direct-target native request path and does not own cast cancellation, native
# queueing, or target mutation.
$viperSerpentTailRules = Read-RequiredSource $viperSerpentTailRulesPath 'VPR Serpent Tail rules'
$normalizedViperSerpentTailRules = $viperSerpentTailRules -replace '\s+', ' '
$viperSerpentTailSelfTests = Read-RequiredSource $viperSerpentTailSelfTestsPath 'VPR Serpent Tail self-tests'
$viperSerpentTailProbe = Read-RequiredSource $viperSerpentTailProbePath 'VPR Serpent Tail runtime probe'
$normalizedViperSerpentTailProbe = $viperSerpentTailProbe -replace '\s+', ' '
$strictWolvesDenDummyResolver = Read-RequiredSource $strictWolvesDenDummyResolverPath 'Strict Wolves Den striking-dummy resolver'
$normalizedStrictWolvesDenDummyResolver = $strictWolvesDenDummyResolver -replace '\s+', ' '
$viperNearAssist = Read-RequiredSource $nearAssistPath 'Near Assist VPR-independence boundary'
$viperMetadataGuard = Read-RequiredSource (Join-Path $pluginServicesRoot 'SeitonMetadataGuard.cs') 'VPR metadata guard'
$normalizedViperMetadataGuard = $viperMetadataGuard -replace '\s+', ' '

Assert-Literals $viperSerpentTailRules @(
    'public const uint ViperJobId = 41;',
    'public const uint WolvesDenStrikingDummyNameId = 541;',
    'public const uint CarrierActionId = 39_183;',
    'public const uint DeathRattleActionId = 39_174;',
    'public const uint TwinfangBiteActionId = 39_175;',
    'public const uint TwinbloodBiteActionId = 39_176;',
    'public const uint UncoiledTwinfangActionId = 39_177;',
    'public const uint UncoiledTwinbloodActionId = 39_178;',
    'public const uint FirstLegacyActionId = 39_179;',
    'public const uint SecondLegacyActionId = 39_180;',
    'public const uint ThirdLegacyActionId = 39_181;',
    'public const uint FourthLegacyActionId = 39_182;',
    'public readonly record struct ViperSerpentTailExposureState(',
    'long Generation,',
    'uint EpisodeActionId,',
    'bool IsCurrentlyExposed,',
    'bool IsSpent,',
    'int ConsecutiveNonFollowUpObservations)',
    'public bool HasCurrentFollowUp =>',
    'public uint CurrentActionId => HasCurrentFollowUp ? EpisodeActionId : 0;',
    'public static ViperSerpentTailExposureState ObserveCarrierExposure(',
    'public static ViperSerpentTailExposureState MarkCarrierExposureSpent(',
    'public static ViperSerpentTailExposureState RetireCarrierExposureAfterExactTargetDrift(',
    'RetireCurrentCarrierExposureAfterSelectedWinnerInvalidation(',
    'public static bool IsCurrentUnspentExposure(',
    'public static bool IsTrackedUnspentExposure(',
    'long ExposureGeneration,',
    'ViperSerpentTailExposureState Exposure,',
    'bool SpendExposure,',
    'UncoiledTwinfangActionId or UncoiledTwinbloodActionId => 20,',
    'FourthLegacyActionId => 5,',
    'public static bool IsEligibleWolvesDenCurrentTarget(',
    'exactVerifiedStrikingDummy || isPlayerCharacter && hostileFlag;',
    'SupportedPvPContext.CrystallineConflict => EnemySlotRules.IsValidSlot(enemySlot),',
    'SupportedPvPContext.WolvesDen => enemySlot == 0,',
    'HeldActionRetryRules.CanAttemptFrozenIntent(',
    'HeldActionRetryRules.RetainsSchedulerFrame(',
    'HeldActionRetryRules.Complete(',
    'HeldActionRetryDisposition Disposition,',
    'ClassifyFollowUpBoundary(',
    'targetStatusBefore != 0',
    'targetStatusAfter != 0',
    'ClientActionAttemptBoundaryRules.Classify(',
    'currentHeldKeyCode == intent.FrozenKeyCode && frozenKeyStillDown',
    'candidate.HasNativeRangeAndLineOfSight'
) 'Exact VPR carrier/follow-up IDs, direct exposure generation, frozen intent, and shared retry policy'
if ([regex]::Matches($viperSerpentTailRules, '\bHeldActionRetryRules\.RetainsSchedulerFrame\s*\(').Count -ne 2 -or
    [regex]::Matches($viperSerpentTailRules, '\bObserveCarrierExposure\s*\(').Count -ne 1 -or
    [regex]::Matches($viperSerpentTailRules, '\bMarkCarrierExposureSpent\s*\(').Count -ne 3 -or
    [regex]::Matches($viperSerpentTailRules, '\bClassifyFollowUpBoundary\s*\(').Count -ne 1 -or
    $normalizedViperSerpentTailRules -notmatch 'if \(IsExactFollowUpAction\(resolvedCarrierActionId\)\).*?previous\.HasTrackedEpisode && previous\.EpisodeActionId == resolvedCarrierActionId.*?IsCurrentlyExposed = true.*?ConsecutiveNonFollowUpObservations = 0.*?var nextGeneration = NextExposureGeneration\(previous\.Generation\);.*?IsSpent: false' -or
    $normalizedViperSerpentTailRules -notmatch 'var misses = Math\.Min\( 2, previous\.ConsecutiveNonFollowUpObservations \+ 1\); if \(previous\.HasTrackedEpisode && misses == 1\).*?IsCurrentlyExposed = false.*?ConsecutiveNonFollowUpObservations = 1.*?new ViperSerpentTailExposureState\( previous\.Generation, 0, IsCurrentlyExposed: false, IsSpent: false, ConsecutiveNonFollowUpObservations: misses\)' -or
    $normalizedViperSerpentTailRules -notmatch 'state\.Generation == generation && state\.EpisodeActionId == actionId \? state with \{ IsSpent = true \}' -or
    $normalizedViperSerpentTailRules -notmatch 'RetireCurrentCarrierExposureAfterSelectedWinnerInvalidation\(.*?selectedWinnerInvalidated\) => selectedWinnerInvalidated \? MarkCarrierExposureSpent\( exposure, exposure\.Generation, exposure\.CurrentActionId\) : exposure;' -or
    $normalizedViperSerpentTailRules -notmatch 'IsTrackedUnspentExposure\(exposure, generation, actionId\) && exposure\.IsCurrentlyExposed' -or
    $normalizedViperSerpentTailRules -notmatch 'if \(!IsTrackedUnspentExposure\( observation\.Exposure, intent\.ExposureGeneration, intent\.ActionId\)\).*?observation\.Exposure\.HasCurrentFollowUp && !observation\.Exposure\.IsSpent.*?return TryCreateIntent\(observation\)' -or
    $normalizedViperSerpentTailRules -notmatch 'ClassifyFollowUpBoundary\(.*?if \(clientReturnedAccepted\) return ClientActionAttemptOutcome\.ClientAccepted; if \(expectedActionId == 0 \|\| targetStatusBefore != 0 \|\| targetStatusAfter != 0 \|\| carrierBefore != expectedActionId \|\| carrierAfter != expectedActionId\).*?return ClientActionAttemptOutcome\.AcceptanceUnknown;.*?return ClientActionAttemptBoundaryRules\.Classify\( false, expectedActionId, before, after\);' -or
    $normalizedViperSerpentTailRules -notmatch 'intent\.IsValid && configurationEnabled && context == intent\.Context.*?!guardSuppressed && !higherPriorityClaimed.*?IsCurrentUnspentExposure\( exposure, intent\.ExposureGeneration, intent\.ActionId\).*?currentHeldKeyCode == intent\.FrozenKeyCode && frozenKeyStillDown.*?IsExactCandidate\(intent, candidate\).*?candidate\.HasNativeRangeAndLineOfSight' -or
    $normalizedViperSerpentTailRules -notmatch 'candidate\.Context == intent\.Context && candidate\.EnemySlot == intent\.EnemySlot && candidate\.Actor == intent\.Target && candidate\.ExactCanonicalIdentity && candidate\.Alive && candidate\.Targetable' -or
    $normalizedViperSerpentTailRules -notmatch 'if \(observation\.HigherPriorityClaimed\).*?HigherPriorityClaimed.*?if \(observation\.ActionHelpersSuppressedByGuard\).*?GuardSuppressed' -or
    $viperSerpentTailRules -match '(?i)\b(?:AcceptedActionEpoch|TriggerToken|TriggerLifetime|TriggerPromotion|TriggerInvocation|QueueAction|UseAction|CancelCast|TargetManager|SetTarget|Stopwatch|Timer|ExpiresAtMilliseconds)\b') {
    throw 'VPR Core must derive one monotone exact carrier exposure, tolerate one flicker, require a stable reset before same-ID rearm, freeze one exact actor/key intent, preserve Purify priority, and own no action, queue, target, cast, or timer boundary.'
}

