) '/seiton debug current decision plus persistent last actual cast-cancel request/native diagnostics'

# One common held-action contract owns native classification and bounded retry.
$clientActionAttemptOutcome = Read-RequiredSource $clientActionAttemptOutcomePath 'Client action attempt outcome rules'
$normalizedClientActionAttemptOutcome = $clientActionAttemptOutcome -replace '\s+', ' '
$clientActionAttemptBoundary = Read-RequiredSource $clientActionAttemptBoundaryPath 'Client action attempt boundary'
$heldActionRetryRules = Read-RequiredSource $heldActionRetryRulesPath 'Held action retry rules'
$normalizedHeldActionRetryRules = $heldActionRetryRules -replace '\s+', ' '
$heldActionRetrySelfTests = Read-RequiredSource $heldActionRetrySelfTestsPath 'Held action retry self-tests'
$heldHelperReservationRules = Read-RequiredSource $heldHelperReservationRulesPath 'Held helper release-reservation rules'
$heldHelperReservationSelfTests = Read-RequiredSource $heldHelperReservationSelfTestsPath 'Held helper release-reservation self-tests'
Assert-Literals $clientActionAttemptOutcome @(
    'ClientRejected = 2',
    'ClientAccepted = 3',
    'AcceptanceUnknown = 4',
    'SoftUnavailable = 5',
    'bool ActionQueued,',
    'uint QueuedActionType,',
    'uint QueuedActionId,',
    'ulong QueuedTargetId,',
    'uint QueuedExtraParam,',
    'uint QueueMode,',
    'uint QueuedComboRouteId,',
    'ushort LastUsedActionSequence,',
    'float AnimationLockSeconds,',
    'uint CastActionId,',
    'uint AdjustedActionId,',
    'bool IsActionOffCooldown,',
    'uint ResourceStatus',
    'before == after',
    '? ClientActionAttemptOutcome.ClientRejected',
    ': ClientActionAttemptOutcome.AcceptanceUnknown',
    'public bool IsCriticalRecoveryActionReady(',
    '(allowOccupiedQueue || !ActionQueued)',
    'public static bool BecameCriticalRecoveryReady(',
    'public static ClientActionAttemptOutcome ClassifyCriticalRecovery('
) 'Complete native attempt fingerprint, strict ordinary classification, and unchanged occupied-queue critical-recovery classification'
Assert-Literals $clientActionAttemptBoundary @(
    'actionManager->ActionQueued',
    '(uint)actionManager->QueuedActionType',
    'actionManager->QueuedActionId',
    '(ulong)actionManager->QueuedTargetId',
    'actionManager->QueuedExtraParam',
    '(uint)actionManager->QueueType',
    'actionManager->QueuedComboRouteId',
    'actionManager->LastUsedActionSequence',
    'actionManager->AnimationLock',
    'actionManager->CastActionId',
    'actionManager->GetAdjustedActionId(actionId)',
    'actionManager->IsActionOffCooldown(ActionType.Action, actionId)',
    'actionManager->CheckActionResources(ActionType.Action, actionId)'
) 'Complete runtime native attempt fingerprint capture'
Assert-Literals $heldActionRetryRules @(
    'NativeRetryThrottleMilliseconds = 50',
    'MaximumNativeAttempts = 8',
    'MinimumLatencyResponseWindowMilliseconds = 100',
    'MaximumLatencyResponseWindowMilliseconds = 1_500',
    'DefaultLatencyResponseWindowMilliseconds = 1_000',
    'public static void ConfigureLatencyResponsePolicy(',
    'Volatile.Write(ref latencyResponseWindowMilliseconds, value)',
    'public static int CurrentMaximumNativeAttempts',
    'MaximumNearQueueableAnimationLockSeconds = 0.050f',
    'allowOccupiedQueue: false',
    '(allowOccupiedQueue || !actionQueued)',
    'public static bool CanAttemptOnBoundaryEdgeOrThrottle(',
    'currentFrameId != lastAttemptFrameId',
    'relevantBoundaryEdge || CanAttempt(state, nowMilliseconds)',
    'public static bool CanAttemptFrozenIntentOnBoundaryEdgeOrThrottle(',
    'ClientActionAttemptOutcome.ClientAccepted =>',
    'Terminal(HeldActionRetryDisposition.AcceptedTerminal)',
    'ClientActionAttemptOutcome.AcceptanceUnknown =>',
    'Terminal(HeldActionRetryDisposition.AmbiguousTerminal)',
    'ClientActionAttemptOutcome.ClientRejected =>',
    'CompleteRejected(previous, nowMilliseconds)',
    'ClientActionAttemptOutcome.SoftUnavailable =>',
    'new HeldActionRetryDecision(previous, HeldActionRetryDisposition.SoftWait)',
    'public static bool RetainsSchedulerFrame(',
    'bool actionSpecificReady,',
    'bool targetSpecificReady = true',
    'actionSpecificReady &&',
    'targetSpecificReady &&',
    'disposition is HeldActionRetryDisposition.RejectedTerminal or',
    'HeldActionRetryDisposition.AmbiguousTerminal'
) 'Shared legacy eight-call retry plus explicit 100-1500-ms clean-false extension, zero-budget soft wait, priority retention, and circuit breaker'
if ($normalizedClientActionAttemptOutcome -notmatch 'public static ClientActionAttemptOutcome Classify\(.*?if \(clientReturnedAccepted\) return ClientActionAttemptOutcome\.ClientAccepted; return before\.IsExactActionReady\(expectedActionId\) && after\.IsExactActionReady\(expectedActionId\) && before == after \? ClientActionAttemptOutcome\.ClientRejected : ClientActionAttemptOutcome\.AcceptanceUnknown;' -or
    $normalizedClientActionAttemptOutcome -notmatch 'public static ClientActionAttemptOutcome ClassifyCriticalRecovery\(.*?before\.IsCriticalRecoveryActionReady\( expectedActionId, allowOccupiedQueue\) && after\.IsCriticalRecoveryActionReady\( expectedActionId, allowOccupiedQueue\) && before == after \? ClientActionAttemptOutcome\.ClientRejected : ClientActionAttemptOutcome\.AcceptanceUnknown;' -or
    $normalizedHeldActionRetryRules -notmatch 'public static bool ShouldLatchHeldKeyUntilRelease\( HeldActionRetryDisposition disposition\) => disposition is HeldActionRetryDisposition\.RejectedTerminal or HeldActionRetryDisposition\.AmbiguousTerminal;' -or
    $heldActionRetryRules -match 'ShouldLatchHeldKeyUntilRelease[\s\S]{0,300}(?:AcceptedTerminal|CancelledTerminal)') {
    throw 'True and ambiguous native outcomes must be terminal; only exhaustion or ambiguity may latch the exact held key until release.'
}
$heldActionRetryTestMethods = @(
    'ProvenFalseRetriesAreThrottledAndBounded',
    'OnlyProvenFalseCanRetainTheFrozenIntent',
    'NativeFalseRequiresAStableReadyBoundaryFingerprint',
    'AcceptedEpisodeDoesNotLatchAContinuousHeldKey',
    'FrozenThrottleAndGlobalWaitRetainOnlyEligiblePriority',
    'InitialExactIntentClaimsCastSoftWaitWithoutSpendingBudget',
    'OptInLatencyWindowExtendsOnlyCleanFalseBudget',
    'CriticalRecoveryCanProveFalseAcrossAnUnchangedOccupiedQueue',
    'CriticalRecoveryRetryWakesOnAnEdgeOrFallbackFrameOnlyOnce'
)
foreach ($method in $heldActionRetryTestMethods) {
    Assert-Literals $heldActionRetrySelfTests @("internal static void $method()") "Held action retry self-test $method"
    Assert-Literals $coreSelfTestProgramForGuardian @("HeldActionRetrySelfTests.$method") "Held action retry test registration $method"
}
if ([regex]::Matches($heldActionRetrySelfTests, '\binternal static void\s+\w+\s*\(').Count -ne 9 -or
    [regex]::Matches($coreSelfTestProgramForGuardian, '\bHeldActionRetrySelfTests\.\w+').Count -ne 9) {
    throw 'All nine shared retry/classification/priority-retention/cast-soft-wait/latency-window/critical-edge tests must remain registered exactly once.'
}
Assert-Literals $heldHelperReservationRules @(
    'public static bool CanObserveExactFrozenOwnership(',
    'exactFrozenOwnershipAlreadyObserved ||',
    '(generation.IsEligible && !generation.IsConsumed)',
    'public static bool CanBeginReleaseReservation(',
    '!textInputActive &&',
    'exactFrozenOwnershipObserved;',
    'currentInputGeneration != releaseInputGeneration',
    'return deadline >= 0 && nowMilliseconds < deadline;'
) 'Exact-owner-only held-helper key-up reservation with an exclusive deadline and new-input cancellation'
$heldHelperReservationTestMethods = @(
    'ReleaseWindowIsBoundedAndExclusive',
    'ConsumedFrozenOwnerMayReserveButDiscoveryCannot',
    'NewInputAndSafetyDriftCancelReleaseReservation'
)
foreach ($method in $heldHelperReservationTestMethods) {
    Assert-Literals $heldHelperReservationSelfTests @("internal static void $method()") "Held helper reservation self-test $method"
    Assert-Literals $coreSelfTestProgramForGuardian @("HeldHelperReservationSelfTests.$method") "Held helper reservation test registration $method"
}
if ([regex]::Matches($heldHelperReservationSelfTests, '\binternal static void\s+\w+\s*\(').Count -ne 3 -or
    [regex]::Matches($coreSelfTestProgramForGuardian, '\bHeldHelperReservationSelfTests\.\w+').Count -ne 3) {
    throw 'All three exact-owner, deadline, consumed-generation, and safety-drift release-reservation tests must remain registered exactly once.'
}

# Optional cross-plugin coordination publishes only an already-consumed exact
# PvP held frame. It must not create a second action lane or leak into PvE.
$criticalUtilityCoordinationRules = Read-RequiredSource $criticalUtilityCoordinationRulesPath 'Critical utility coordination rules'
$criticalUtilityCoordinationService = Read-RequiredSource $criticalUtilityCoordinationServicePath 'Critical utility coordination IPC service'
$criticalUtilityCoordinationSelfTests = Read-RequiredSource $criticalUtilityCoordinationSelfTestsPath 'Critical utility coordination self-tests'
$emergencyInputCoordinatorForCoordination = Read-RequiredSource $emergencyInputCoordinatorPath 'Critical utility held-frame callback'
$personalStatusForCoordination = Read-RequiredSource $personalStatusPath 'Critical utility runtime lifecycle'
Assert-Literals $criticalUtilityCoordinationRules @(
    'SupportedPvPContext.CrystallineConflict or',
    'SupportedPvPContext.WolvesDen',
    'localPlayerAlive &&',
    '!hardReset &&',
    'sharedHeldFrameConsumed'
) 'CC/Wolves-Den-only critical utility publication gate'
Assert-Literals $criticalUtilityCoordinationService @(
    'IpcName = "SeitonSense.IsCriticalUtilityClaimed"',
    'ClaimLeaseMilliseconds = 125',
    'provider.RegisterFunc(IsClaimedForIpc)',
    'configuration.EnablePvpLatencyResponseHelper',
    'Volatile.Read(ref eligible) != 0',
    'Volatile.Read(ref claimed) != 0',
    'provider.UnregisterFunc()'
) 'Bounded opt-in critical utility IPC lease'
Assert-Literals $emergencyInputCoordinatorForCoordination @(
    'private readonly Action? onConsumed;',
